private fun money(v:Long)=DecimalFormat("#,###").format(v)
private fun fa(v:Any)=v.toString().map{"0123456789".indexOf(it).let{n->if(n>=0)"۰۱۲۳۴۵۶۷۸۹"[n] else it}}.joinToString("")
private fun date(ms:Long):String{val p=PersianDate.from(ms);return "${fa(p.day)} ${persianMonthName(p.month)} ${fa(p.year)}"}

@Composable fun MentoOnboarding(auth:GoogleAuthManager,onUser:(LocalGoogleUser)->Unit,onOffline:()->Unit,message:(String)->Unit){val c=LocalContext.current;val s=rememberCoroutineScope();Column(Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background).padding(28.dp),horizontalAlignment=Alignment.CenterHorizontally){Spacer(Modifier.weight(.7f));Image(painterResource(R.drawable.mento_logo),"Mento",Modifier.size(104.dp));Spacer(Modifier.height(24.dp));Text("پرداخت‌ها، مرتب و به‌موقع",fontSize=25.sp,fontWeight=FontWeight.ExtraBold,color=MaterialTheme.colorScheme.onBackground,textAlign=TextAlign.Center);Spacer(Modifier.height(10.dp));Text("اقساط، اجاره و هزینه‌ها را خصوصی روی گوشی نگه دارید و موعدی را از دست ندهید.",fontSize=14.sp,lineHeight=22.sp,color=MaterialTheme.colorScheme.onSurfaceVariant,textAlign=TextAlign.Center);Spacer(Modifier.height(34.dp));Button({if(!auth.configured)message("ورود گوگل تنظیم نشده")else s.launch{runCatching{auth.signIn(c as Activity)}.onSuccess(onUser).onFailure{message(it.message?:"ورود انجام نشد")}}},Modifier.fillMaxWidth().height(54.dp),shape=RoundedCornerShape(16.dp)){Icon(Icons.Outlined.AccountCircle,null);Spacer(Modifier.width(8.dp));Text("ادامه با Google",fontWeight=FontWeight.Bold)};TextButton(onOffline){Text("فعلاً بدون حساب ادامه می‌دهم")};Spacer(Modifier.weight(1f));Text("اطلاعات مالی روی همین دستگاه می‌ماند و در فضای ابری آپلود نمی‌شود.",fontSize=11.sp,color=MaterialTheme.colorScheme.onSurfaceVariant,textAlign=TextAlign.Center)}}

@Composable fun MentoHomeScreen(data:List<PaymentWithInstallments>,open:(PaymentWithInstallments)->Unit,toggle:(Installment)->Unit,modifier:Modifier){val now=System.currentTimeMillis();val current=PersianDate.from(now);val monthRows=data.mapNotNull{r->r.installments.firstOrNull{val p=PersianDate.from(it.dueAt);p.year==current.year&&p.month==current.month}?.let{r to it}};val openMonth=monthRows.map{it.second}.filter{it.paidAt==null}.sortedBy{it.dueAt};var q by remember{mutableStateOf("")};var f by remember{mutableStateOf("همه")};LazyColumn(modifier.fillMaxSize().padding(horizontal=16.dp),verticalArrangement=Arrangement.spacedBy(9.dp),contentPadding=PaddingValues(bottom=110.dp)){item{Row(Modifier.fillMaxWidth().padding(top=8.dp),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.Bottom){Column{Text("این ماه",fontSize=23.sp,fontWeight=FontWeight.ExtraBold);Text("پرداخت‌های ${persianMonthName(current.month)}",fontSize=12.sp,color=MM)};Text(date(now),fontSize=11.sp,color=MM)}};item{Card(colors=CardDefaults.cardColors(MI),shape=RoundedCornerShape(24.dp),modifier=Modifier.animateContentSize()){Column(Modifier.fillMaxWidth().padding(18.dp)){Text("این‌قدر باید بدی",color=Color.White.copy(.68f));Text("${money(openMonth.sumOf{it.amount})} تومان",color=Color.White,fontSize=27.sp,fontWeight=FontWeight.ExtraBold);Spacer(Modifier.height(14.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("${fa(openMonth.size)} پرداخت این ماه",color=Color.White.copy(.75f));Text(openMonth.firstOrNull()?.let{"بعدی: ${date(it.dueAt)}"}?:"این ماه چیزی نمونده ✨",color=Color(0xFF83E3C4))}}}};item{OutlinedTextField(q,{q=it},Modifier.fillMaxWidth(),shape=RoundedCornerShape(16.dp),singleLine=true,leadingIcon={Icon(Icons.Outlined.Search,null)},placeholder={Text("جست‌وجوی پرداخت این ماه")})};item{LazyRow(horizontalArrangement=Arrangement.spacedBy(7.dp)){items(listOf("همه","در انتظار","معوق","انجام‌شده")){x->FilterChip(f==x,{f=x},{Text(x)})}}};val shown=monthRows.filter{(r,_)->r.item.title.contains(q,true)||r.item.category.contains(q,true)}.filter{(_,i)->when(f){"در انتظار"->i.paidAt==null&&i.dueAt>=now;"معوق"->i.paidAt==null&&i.dueAt<now;"انجام‌شده"->i.paidAt!=null;else->true}};if(shown.isEmpty())item{Empty("برای این ماه پرداختی در این بخش نیست")};items(shown,key={it.first.item.id}){(r,i)->PaymentCard(r,i,{open(r)}){toggle(i)}}}}
@Composable private fun PaymentCard(r:PaymentWithInstallments,i:Installment,open:()->Unit,pay:()->Unit){val done=i.paidAt!=null;Card(onClick=open,shape=RoundedCornerShape(18.dp),colors=CardDefaults.cardColors(MaterialTheme.colorScheme.surface),border=BorderStroke(1.dp,if(done)MT.copy(.45f) else MaterialTheme.colorScheme.outline),modifier=Modifier.animateContentSize()){Row(Modifier.fillMaxWidth().padding(12.dp),verticalAlignment=Alignment.CenterVertically){Surface(color=if(done)MT.copy(.12f) else MS,shape=RoundedCornerShape(14.dp),modifier=Modifier.size(44.dp)){Box(contentAlignment=Alignment.Center){Icon(icon(r.item.iconKey),null,tint=if(done)MT else MP)}};Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text(r.item.title,fontWeight=FontWeight.Bold);Text(if(done)"انجام شد · ${date(i.dueAt)}" else "${r.item.category} · ${date(i.dueAt)}",fontSize=11.sp,color=if(done)MT else if(i.dueAt<System.currentTimeMillis())MR else MM);Text("${money(i.amount)} تومان",fontSize=12.sp,fontWeight=FontWeight.SemiBold)};Surface(onClick={if(!done)pay()},shape=CircleShape,color=if(done)MT else MaterialTheme.colorScheme.surface,border=BorderStroke(1.5.dp,if(done)MT else MP),modifier=Modifier.size(36.dp)){Box(contentAlignment=Alignment.Center){Icon(Icons.Outlined.Done,if(done)"انجام شده" else "ثبت پرداخت",tint=if(done)Color.White else MP,modifier=Modifier.size(19.dp))}}}}}

