  item{Action(Icons.Outlined.Alarm,"مجوز آلارم دقیق","اجرای هشدار در ساعت انتخابی"){if(Build.VERSION.SDK_INT>=31)c.startActivity(Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:${c.packageName}")))}}
  item{Action(Icons.Outlined.BatterySaver,"بهینه‌سازی باتری","اگر یادآورها دیر اجرا می‌شوند، محدودیت باتری Mento را بررسی کنید"){c.startActivity(Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS))}}
  item{Action(Icons.Outlined.DarkMode,"ظاهر برنامه",when(themeMode){"dark"->"تیره";"light"->"روشن";else->"هماهنگ با گوشی"}){themeDialog=true}}
  item{Action(Icons.Outlined.Language,"زبان برنامه","فارسی"){languageDialog=true}}
  item{Action(Icons.Outlined.Backup,"بکاپ رمزدار","ذخیره روی گوشی"){password="";passwordMode="export"}}
  item{Action(Icons.Outlined.Restore,"بازیابی بکاپ","از فایل Mento"){password="";passwordMode="import"}}
  item{Surface(color=MS,shape=RoundedCornerShape(16.dp)){Text("ورود یا خروج Google داده‌های مالی را حذف نمی‌کند. پیش از حذف برنامه بکاپ بگیرید.",Modifier.padding(14.dp),fontSize=11.sp,color=MM)}}
 }
