 if(themeDialog)AlertDialog(onDismissRequest={themeDialog=false},title={Text("ظاهر برنامه")},text={Column{listOf("system" to "هماهنگ با گوشی","light" to "روشن","dark" to "تیره").forEach{(key,label)->Row(Modifier.fillMaxWidth().clickable{setTheme(key);themeDialog=false}.padding(12.dp),verticalAlignment=Alignment.CenterVertically){RadioButton(themeMode==key,{setTheme(key);themeDialog=false});Text(label)}}}},confirmButton={TextButton({themeDialog=false}){Text("بستن")}})
