 backupSummary?.let{summary->AlertDialog(onDismissRequest={backupSummary=null;restoreUri=null},title={Text("پیش‌نمایش بکاپ")},text={Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Text("${fa(summary.items)} آیتم پرداخت");Text("${fa(summary.installments)} قسط");Text("${fa(summary.receipts)} فایل رسید");Text("ادغام، اطلاعات فعلی را نگه می‌دارد. جایگزینی، اطلاعات فعلی را پاک می‌کند.",fontSize=11.sp,color=MM)}},confirmButton={Row{TextButton({val u=restoreUri?:return@TextButton;backupSummary=null;vm.import(u,password,false){r->message(r.fold({"بکاپ با اطلاعات فعلی ادغام شد"},{e->e.message?:"خطا"}))}}){Text("ادغام")};TextButton({val u=restoreUri?:return@TextButton;backupSummary=null;vm.import(u,password,true){r->message(r.fold({"بکاپ جایگزین شد"},{e->e.message?:"خطا"}))}}){Text("جایگزینی",color=MR)}}},dismissButton={TextButton({backupSummary=null;restoreUri=null}){Text("انصراف")}})}
